export function HandwrittenLogo({
  className,
  duration = 2.4,
  delay = 0.35,
}: {
  className?: string;
  duration?: number;
  delay?: number;
}) {
  const pathRef = React.useRef<SVGPathElement>(null);

  React.useEffect(() => {
    const p = pathRef.current;
    if (!p) return;
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const len = p.getTotalLength();
    if (reduced) {
      gsap.set(p, { strokeDasharray: len, strokeDashoffset: 0 });
      return;
    }
    gsap.set(p, { strokeDasharray: len, strokeDashoffset: len });
    const tween = gsap.to(p, {
      strokeDashoffset: 0,
      duration,
      delay,
      ease: 'power2.inOut',
    });
    return () => {
      tween.kill();
    };
  }, [duration, delay]);

  return (
    <svg
      viewBox={VIEW_BOX}
      aria-hidden
      className={cn('h-14 sm:h-16 w-auto text-accent overflow-visible', className)}
      fill="none"
    >
      <path
        ref={pathRef}
        d={PATH_D}
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}
